def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = 0
    for a in op:
        if a == 'D':
            opp_d += 1
    my_d = 0
    for a in me:
        if a == 'D':
            my_d += 1

    last_me = me[-1]
    last_op = op[-1]

    recent_n = min(10, n)
    recent_op_d = 0
    for i in range(n - recent_n, n):
        if op[i] == 'D':
            recent_op_d += 1

    opp_crate = float(n - opp_d) / float(n)

    if n >= 96:
        if opp_crate >= 0.7 and recent_op_d == 0:
            return 'C'
        return 'D'

    if opp_d == 0:
        if n >= 70 and rng.random() < 0.15:
            return 'D'
        return 'C'

    streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak += 1
        else:
            break

    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D':
            my_streak_d += 1
        else:
            break

    if n < 6:
        if opp_d >= 2:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    if opp_crate <= 0.15:
        return 'D'

    if recent_op_d >= 7:
        if last_op == 'C' and rng.random() < 0.12:
            return 'C'
        return 'D'

    if streak >= 1:
        if streak == 1:
            if last_me == 'D':
                return 'C'
            return 'D'
        if streak == 2:
            if opp_crate >= 0.55 and rng.random() < 0.35:
                return 'C'
            return 'D'
        if opp_crate >= 0.5 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if recent_op_d == 0:
        if my_streak_d >= 1:
            return 'C'
        if opp_crate < 0.45 and n > 12:
            if rng.random() < 0.18:
                return 'D'
        if opp_crate >= 0.8 and n >= 70 and rng.random() < 0.1:
            return 'D'
        return 'C'

    if recent_op_d <= 2:
        if opp_crate >= 0.6:
            if rng.random() < 0.12:
                return 'D'
            return 'C'
        if opp_crate >= 0.35:
            return 'C'
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    if opp_crate >= 0.5:
        if rng.random() < 0.55:
            return 'C'
        return 'D'

    if rng.random() < 0.2:
        return 'C'
    return 'D'
